const input = $json || {};

let documents = input.documents || input.docs || [];

if (!Array.isArray(documents)) {
  documents = [documents];
}

const normalized = [];

for (const doc of documents) {
  if (!doc) continue;

  const title = String(
    doc.title ||
    doc.name ||
    doc.file_name ||
    doc.filename ||
    'Untitled Document'
  ).trim();

  const content = String(
    doc.content ||
    doc.text ||
    doc.body ||
    doc.description ||
    ''
  ).trim();

  if (!content) continue;

  normalized.push({
    document_id: doc.id || doc.document_id || null,
    title,
    source: doc.source || 'documentation',
    mime_type: doc.mime_type || doc.mimeType || null,
    url: doc.url || doc.web_url || null,
    content,
    updated_at: doc.updated_at || doc.modifiedTime || null
  });
}

return [
  {
    json: {
      status: 'documents_normalized',
      document_count: normalized.length,
      documents: normalized
    }
  }
];

const data = $json || {};
const documents = data.documents || [];

const evidence = [];
const decisions = [];
const tasks = [];
const dependencies = [];
const requirements = [];

function addEvidence(type, title, content, document) {
  evidence.push({
    evidence_id: `doc-${evidence.length + 1}`,
    type,
    title,
    content,
    source: 'documentation',
    document: document.title,
    document_id: document.document_id || null,
    url: document.url || null
  });
}

for (const doc of documents) {
  const content = doc.content || '';
  const lower = content.toLowerCase();

  const lines = content
    .split(/\r?\n/)
    .map(x => x.trim())
    .filter(Boolean);

  for (const line of lines) {
    const clean = line.replace(/^[-*#>\d.]+\s*/, '').trim();
    if (!clean || clean.length < 8) continue;

    if (/\b(decision|decided|we will use|chosen|choice|architecture decision)\b/i.test(clean)) {
      addEvidence('decision', clean.substring(0, 120), clean, doc);
      decisions.push(clean);
      continue;
    }

    if (/\b(todo|to do|task|implement|add|build|develop|pending|next step)\b/i.test(clean)) {
      addEvidence('task', clean.substring(0, 120), clean, doc);
      tasks.push(clean);
      continue;
    }

    if (/\b(depends on|dependency|requires|requirement|prerequisite|needs)\b/i.test(clean)) {
      addEvidence('dependency', clean.substring(0, 120), clean, doc);
      dependencies.push(clean);
      continue;
    }

    if (/\b(requirement|must|should|shall|goal|objective)\b/i.test(clean)) {
      addEvidence('requirement', clean.substring(0, 120), clean, doc);
      requirements.push(clean);
      continue;
    }

    if (/\b(problem|issue|limitation|blocker|warning|risk)\b/i.test(clean)) {
      addEvidence('problem', clean.substring(0, 120), clean, doc);
      continue;
    }

    if (/\b(solution|fix|resolved|implemented|workaround)\b/i.test(clean)) {
      addEvidence('solution', clean.substring(0, 120), clean, doc);
      continue;
    }
  }

  if (/\barchitecture\b/i.test(lower)) {
    addEvidence(
      'architecture',
      `${doc.title} architecture context`,
      content.substring(0, 1500),
      doc
    );
  }
}

function unique(values) {
  return [...new Set(values.map(v => String(v).trim()).filter(Boolean))];
}

return [
  {
    json: {
      status: 'documentation_evidence_extracted',
      document_count: documents.length,
      evidence_count: evidence.length,
      evidence: evidence,
      decisions: unique(decisions),
      tasks: unique(tasks),
      dependencies: unique(dependencies),
      requirements: unique(requirements),
      summary: {
        documents: documents.length,
        evidence: evidence.length,
        decisions: unique(decisions).length,
        tasks: unique(tasks).length,
        dependencies: unique(dependencies).length,
        requirements: unique(requirements).length
      }
    }
  }
];

const data = $json || {};

const evidence = data.evidence || [];
const decisions = data.decisions || [];
const tasks = data.tasks || [];
const dependencies = data.dependencies || [];
const requirements = data.requirements || [];

return [
  {
    json: {
      status: 'documentation_context_ready',
      source: 'Docs',
      documents_processed: data.document_count || 0,
      documentation_context: {
        evidence,
        decisions,
        tasks,
        dependencies,
        requirements
      },
      summary: data.summary || {}
    }
  }
];
